const generatedSet = new Set(generatedFiles.filter((file) => file.endsWith('.md')));
function walk(dir) { const out = []; if (!existsSync(dir)) return out; for (const entry of readdirSync(dir, { withFileTypes: true })) { const file = path.join(dir, entry.name).replaceAll(path.sep, '/'); if (entry.isDirectory()) out.push(...walk(file)); else if (entry.isFile() && entry.name.endsWith('.md')) out.push(file); } return out; }
function read(file) { try { return readFileSync(file, 'utf8'); } catch { return ''; } }
function taskForDoc(file) { const f = file.toLowerCase(); if (f.includes('billing') || f.includes('purchase')) return ['AR-BILL-EPIC','AR-BILL-002']; if (f.includes('pricing') || f.includes('entitlement')) return ['AR-LIC-001','AR-SITE-005']; if (f.includes('license')) return ['AR-LIC-EPIC','AR-COM-003']; if (f.includes('seo') || f.includes('geo')) return ['AR-SEO-EPIC','AR-GEO-EPIC']; if (f.includes('competitive')) return ['AR-COMP-EPIC','AR-COMP-001']; if (f.includes('rule') || f.includes('risk') || f.includes('score')) return ['AR-CAT-EPIC','AR-ENG-003']; if (f.includes('github_action') || f.includes('github-action')) return ['AR-COM-007','AR-DOC-004']; if (f.includes('json')) return ['AR-DOC-001']; if (f.includes('cli')) return ['AR-COM-006','AR-DOC-003']; if (f.includes('privacy') || f.includes('legal')) return ['AR-LEG-001','AR-SITE-019']; if (f.includes('trust') || f.includes('security')) return ['AR-SITE-017','AR-SEC-001']; if (f.includes('benchmark') || f.includes('fixture')) return ['AR-ENG-EPIC','AR-ENG-005']; if (f.includes('site') || f.includes('browser')) return ['AR-SITE-EPIC','AR-UX-001']; if (f.includes('go_to_market')) return ['AR-ACQ-001','AR-MARKET-001']; if (f.includes('onboarding')) return ['AR-ONB-EPIC','AR-ONB-004']; if (f.includes('mcp')) return ['AR-SITE-007','AR-INT-002']; return ['AR-GOV-003']; }
const docs = ['README.md','ROADMAP.md','AGENTREADY_PROJECT_CONTEXT.md',...walk('docs/agentready')];
const document_coverage = [...new Set(docs)].filter((file) => !generatedSet.has(file)).map((file) => { const text = read(file); const historical = file.includes('/history/') || file.includes('/legacy/') || text.includes('Status: HISTORICAL') || text.includes('HISTORICAL') || text.includes('SUPERSEDED BY'); return { document: file, status: historical ? 'HISTORICAL' : 'ACTIVE', task_ids: historical ? ['AR-GOV-001'] : taskForDoc(file) }; });

